  ('b0000000-0000-0000-0000-000000000029', '노아 포토카드 세트', '작업실 비하인드 사진 8장을 담은 포토카드 세트입니다.', 15000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000008', 0, NOW(), NOW(), 'https://placehold.co/600x600/dbeafe/1e40af?text=NOAH+Photocard+Set&font=noto-sans', '0199de80-0000-7000-8000-00000000a002'),
