  ('b0000000-0000-0000-0000-000000000039', '리오 시그니처 티셔츠', '리오의 손글씨 로고를 프린트한 코튼 반팔 티셔츠입니다.', 39000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000008', 0, NOW(), NOW(), 'https://placehold.co/600x600/dcfce7/166534?text=RIO+T-Shirt&font=noto-sans', '0199de80-0000-7000-8000-00000000a005'),
  ('b0000000-0000-0000-0000-000000000040', '유노 공식 응원봉', '유노의 시그니처 컬러로 빛나는 공식 응원봉입니다. AA 건전지 3개가 필요합니다.', 45000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000008', 0, NOW(), NOW(), 'https://placehold.co/600x600/e2e8f0/475569?text=YUNO+Light+Stick&font=noto-sans', '0199de80-0000-7000-8000-00000000a006'),
  ('b0000000-0000-0000-0000-000000000041', '유노 포토카드 세트', '재즈 세션 녹음 현장 사진 8장을 담은 포토카드 세트입니다.', 15000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000008', 0, NOW(), NOW(), 'https://placehold.co/600x600/e2e8f0/475569?text=YUNO+Photocard+Set&font=noto-sans', '0199de80-0000-7000-8000-00000000a006'),
